package com.deardiary.privateapp;
import android.view.*;import android.webkit.*;import android.widget.*;import android.graphics.*;import java.lang.reflect.*;import java.io.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class)@Config(sdk=28,manifest=Config.NONE,qualifiers="w820dp-h412dp-land-mdpi")@GraphicsMode(GraphicsMode.Mode.NATIVE)
public class RoomReactionRenderTest{
 void set(MainActivity a,String n,Object v)throws Exception{Field f=MainActivity.class.getDeclaredField(n);f.setAccessible(true);f.set(a,v);}
 @Test public void landscapeOverlayRendersAndCleans()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).get();FrameLayout root=new FrameLayout(a);root.setBackgroundColor(Color.rgb(24,20,29));TextView video=new TextView(a);video.setText("Synthetic fullscreen video surface");video.setTextColor(Color.rgb(200,180,200));video.setGravity(Gravity.CENTER);root.addView(video,new FrameLayout.LayoutParams(-1,-1));WebView web=new WebView(a);web.loadUrl("https://dear-diary-app.github.io/dear-diary/#/room");set(a,"root",root);set(a,"web",web);set(a,"roomFullscreen",video);set(a,"unlocked",true);set(a,"lastFullscreenReaction",-1000L);MainActivity.foreground=true;root.measure(View.MeasureSpec.makeMeasureSpec(820,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(412,View.MeasureSpec.EXACTLY));root.layout(0,0,820,412);Method show=MainActivity.class.getDeclaredMethod("showFullscreenReaction",String.class);show.setAccessible(true);show.invoke(a,"❤️");assertEquals(2,root.getChildCount());View emoji=root.getChildAt(1);assertFalse(emoji.isClickable());assertFalse(emoji.isFocusable());root.measure(View.MeasureSpec.makeMeasureSpec(820,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(412,View.MeasureSpec.EXACTLY));root.layout(0,0,820,412);emoji.animate().cancel();emoji.setAlpha(1);emoji.setTranslationY(-100);Bitmap bitmap=Bitmap.createBitmap(820,412,Bitmap.Config.ARGB_8888);root.draw(new Canvas(bitmap));try(FileOutputStream out=new FileOutputStream("/downloads/room216-preview/native-fullscreen.png")){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}Method clear=MainActivity.class.getDeclaredMethod("clearFullscreenReactions");clear.setAccessible(true);clear.invoke(a);assertEquals(1,root.getChildCount());MainActivity.foreground=false;}
}
